// @FIGURE_CODE_BEGIN
/* ---------- geometry constants (viewBox units) ---------- */
var W = 1000, H = 620;
var lensX = 600, axisY = 290;      // lens slightly right of center
var f = 100;                       // focal length in slider units
var S = 1.25;                      // px per unit
var h_o = 60;                      // object height in units
var fPx = f * S, hoPx = h_o * S;
var tipY = axisY - hoPx;
var lensHalf = 175;

/* ---------- state ---------- */
var d_o = 160;
var showMeas = false;
var selectedRay = 0;
var emphasizeImage = false;

var C_RED = '#d43d3d', C_GREEN = '#57a33f', C_PURPLE = '#7e56a6';
var C_DIM = '#3f3f3f', C_AXIS = '#3a3a3a';

var draw = SVG().addTo('#container').size('100%', '100%');
draw.viewbox(0, 0, W, H);

var rayRules = {
  1: 'Ray 1 leaves the object tip parallel to the axis, bends at the lens, and passes through the FAR focal point F. Its defining marker is the far F — watch it pulse.',
  2: 'Ray 2 aims straight at the center of the thin lens and passes through undeviated. Its defining marker is the lens center — watch it pulse.',
  3: 'Ray 3 travels through the NEAR focal point F and emerges from the lens parallel to the axis. Its defining marker is the near F — watch it pulse.'
};

/* ---------- small helpers ---------- */
function norm(v) { var l = Math.hypot(v[0], v[1]); return [v[0] / l, v[1] / l]; }
function along(p, d, L) { return [p[0] + d[0] * L, p[1] + d[1] * L]; }

function arrowHead(g, x, y, ang, size, color) {
  var c = Math.cos(ang), s = Math.sin(ang);
  var bx = x - size * c, by = y - size * s;
  var px = -s, py = c, w = size * 0.45;
  g.polygon([x, y, bx + px * w, by + py * w, bx - px * w, by - py * w]).fill(color).stroke('none');
}
function arrowOnSeg(g, p, q, t, size, color) {
  var x = p[0] + (q[0] - p[0]) * t, y = p[1] + (q[1] - p[1]) * t;
  arrowHead(g, x, y, Math.atan2(q[1] - p[1], q[0] - p[0]), size, color);
}
function dimBracket(g, x1, x2, y, color, dashed) {
  var w = Math.abs(x2 - x1);
  var as = Math.min(9, Math.max(4, w / 6));
  var ln = g.line(x1, y, x2, y).stroke({ color: color, width: 1.6 });
  if (dashed) ln.attr('stroke-dasharray', '6,4');
  g.line(x1, y - 7, x1, y + 7).stroke({ color: color, width: 1.3 });
  g.line(x2, y - 7, x2, y + 7).stroke({ color: color, width: 1.3 });
  arrowHead(g, x1, y, Math.PI, as, color);
  arrowHead(g, x2, y, 0, as, color);
}
function vDim(g, x, yTop, yBot, color) {
  g.line(x, yTop, x, yBot).stroke({ color: color, width: 1.6 });
  arrowHead(g, x, yTop, -Math.PI / 2, 8, color);
  arrowHead(g, x, yBot, Math.PI / 2, 8, color);
}
function halo(el) {
  el.attr({ 'paint-order': 'stroke', stroke: '#fff', 'stroke-width': 3, 'stroke-linejoin': 'round' });
  return el;
}
function subLabel(g, x, y, base, sub, size, color, anchor) {
  var t = g.text(function (add) {
    add.tspan(base);
    var s2 = add.tspan(sub);
    s2.attr('baseline-shift', 'sub');
    s2.font('size', Math.round(size * 0.7));
  });
  t.font({ size: size, family: 'Georgia, serif', 'font-style': 'italic', anchor: anchor || 'middle' });
  t.fill(color).attr({ x: x, y: y });
  return halo(t);
}
function clickable(el, tip, title, body) {
  el.css('cursor', 'pointer');
  el.on('mousemove', function (e) { showTooltip(tip, e); });
  el.on('mouseleave', function () { hideTooltip(); });
  el.on('click', function (e) { showPopup(title, body); e.stopPropagation(); });
}
function pulse(g, x, y, r) {
  var ring = g.circle(r || 15).center(x, y).fill('none')
    .stroke({ color: '#ff9d00', width: 3, opacity: 0.95 });
  try { ring.animate(900).attr({ opacity: 0.15 }).loop(true, true); } catch (e) { }
  return ring;
}

/* ---------- main render ---------- */
function render() {
  draw.clear();
  var g = draw.group();

  var d_oPx = d_o * S;
  var objX = lensX - d_oPx;
  var Fn = [lensX - fPx, axisY], Ff = [lensX + fPx, axisY];
  var T = [objX, tipY], C = [lensX, axisY], B1 = [lensX, tipY];
  var nearF = Math.abs(d_o - f) < 0.5;
  var d_i = nearF ? Infinity : f * d_o / (d_o - f);
  var real = d_i > 0;
  var imgX = lensX + d_i * S;
  var imgTipY = axisY + (d_i / d_o) * hoPx;
  var imgOn = isFinite(d_i) && imgX > 20 && imgX < 978 && imgTipY > 15 && imgTipY < 605;
  var y3 = nearF ? axisY : axisY + hoPx * fPx / (d_oPx - fPx);
  var B3 = [lensX, y3];

  var dir1 = norm([fPx, hoPx]);          // B1 -> far F
  var dir2 = norm([d_oPx, hoPx]);        // T -> center
  var Lbig = 2600;
  var tImg1 = imgOn ? (imgX - lensX) / dir1[0] : 0;
  var t1 = imgOn ? tImg1 + 90 : Lbig;
  var t2 = imgOn ? Math.hypot(imgX - lensX, imgTipY - axisY) + 90 : Lbig;
  var r1pts = [T, B1, along(B1, dir1, t1)];
  var r2pts = [T, C, along(C, dir2, t2)];
  var r3endX = imgOn ? imgX + 90 : 1060;
  var r3pts = nearF ? [T, [T[0], axisY + 120]] : [T, B3, [r3endX, y3]];

  /* axis + centerline */
  g.line(15, axisY, 988, axisY).stroke({ color: C_AXIS, width: 1.5 });
  g.line(lensX, 96, lensX, 486).stroke({ color: '#8a8a8a', width: 1.2, dasharray: '7,6' });

  /* lens */
  var grad = draw.gradient('linear', function (add) {
    add.stop(0, '#a9cee6'); add.stop(0.5, '#eaf6fc'); add.stop(1, '#a9cee6');
  }).from(0, 0).to(1, 0);
  var lt = axisY - lensHalf, lb = axisY + lensHalf, cw = 55;
  var lensPath = 'M' + lensX + ',' + lt +
    ' C' + (lensX + cw) + ',' + (lt + 70) + ' ' + (lensX + cw) + ',' + (lb - 70) + ' ' + lensX + ',' + lb +
    ' C' + (lensX - cw) + ',' + (lb - 70) + ' ' + (lensX - cw) + ',' + (lt + 70) + ' ' + lensX + ',' + lt + ' Z';
  var lens = g.path(lensPath).fill(grad).stroke({ color: '#4d84a8', width: 2 });
  lens.attr('fill-opacity', 0.85);
  clickable(lens, 'Converging lens (f = ' + f + ')', 'Thin converging lens',
    'All refraction is modeled as a single bend at the center plane (dashed line). That is why the ray through the center goes straight and the other two bend once.');

  /* dashed backward extensions for a virtual image */
  if (!real && isFinite(d_i)) {
    var e1 = norm([B1[0] - Ff[0], B1[1] - Ff[1]]);
    var e2 = norm([T[0] - C[0], T[1] - C[1]]);
    var tv1 = Math.max((imgX - B1[0]) / e1[0] + 70, 80);
    var tv2 = Math.max((imgX - T[0]) / e2[0] + 70, 80);
    g.polyline([B1, along(B1, e1, tv1)]).fill('none')
      .stroke({ color: C_RED, width: 2, dasharray: '7,6' });
    g.polyline([T, along(T, e2, tv2)]).fill('none')
      .stroke({ color: C_GREEN, width: 2, dasharray: '7,6' });
    g.polyline([B3, [Math.min(imgX - 70, B3[0] - 40), y3]]).fill('none')
      .stroke({ color: C_PURPLE, width: 2, dasharray: '7,6' });
  }

  /* the three principal rays */
  var rays = [
    { pts: r1pts, color: C_RED, idx: 1, tip: 'Ray 1 — click for its rule' },
    { pts: r2pts, color: C_GREEN, idx: 2, tip: 'Ray 2 — click for its rule' },
    { pts: r3pts, color: C_PURPLE, idx: 3, tip: 'Ray 3 — click for its rule' }
  ];
  rays.forEach(function (r) {
    if (selectedRay === r.idx) {
      g.polyline(r.pts).fill('none')
        .stroke({ color: r.color, width: 9, opacity: 0.22, linecap: 'round', linejoin: 'round' });
    }
    g.polyline(r.pts).fill('none')
      .stroke({ color: r.color, width: selectedRay === r.idx ? 5 : 2.5, linecap: 'round', linejoin: 'round' });
    var hit = g.polyline(r.pts).fill('none').stroke({ color: '#000', opacity: 0, width: 22 });
    hit.css('cursor', 'pointer');
    hit.on('mousemove', function (e) { showTooltip(r.tip, e); });
    hit.on('mouseleave', function () { hideTooltip(); });
    hit.on('click', function (e) {
      selectedRay = (selectedRay === r.idx) ? 0 : r.idx;
      render();
      if (selectedRay) showPopup('Ray ' + r.idx, rayRules[r.idx]); else hidePopup();
      e.stopPropagation();
    });
  });

  /* direction arrowheads on the rays */
  arrowOnSeg(g, T, B1, 0.55, 9, C_RED);
  arrowHead(g, B1[0] + dir1[0] * (imgOn ? Math.max(60, 0.45 * tImg1) : 175),
    B1[1] + dir1[1] * (imgOn ? Math.max(60, 0.45 * tImg1) : 175),
    Math.atan2(dir1[1], dir1[0]), 9, C_RED);
  arrowOnSeg(g, T, C, 0.5, 9, C_GREEN);
  arrowHead(g, C[0] + dir2[0] * (imgOn ? t2 - 35 : 190), C[1] + dir2[1] * (imgOn ? t2 - 35 : 190),
    Math.atan2(dir2[1], dir2[0]), 9, C_GREEN);
  if (!nearF) {
    arrowOnSeg(g, T, B3, 0.45, 9, C_PURPLE);
    arrowHead(g, imgOn ? imgX + 55 : lensX + 200, y3, 0, 9, C_PURPLE);
  } else {
    arrowHead(g, T[0], axisY + 60, Math.PI / 2, 9, C_PURPLE);
  }

  /* ray number labels */
  halo(g.text('1').font({ size: 17, 'font-weight': 'bold', family: 'sans-serif', anchor: 'middle' })
    .fill(C_RED).attr({ x: T[0] + 0.42 * d_oPx, y: tipY - 12 }));
  halo(g.text('2').font({ size: 17, 'font-weight': 'bold', family: 'sans-serif', anchor: 'middle' })
    .fill(C_GREEN).attr({ x: T[0] + 0.45 * d_oPx + 8, y: tipY + 0.45 * hoPx - 12 }));
  var l3 = real
    ? [T[0] + 0.3 * (Fn[0] - T[0]) - 4, T[1] + 0.3 * (Fn[1] - T[1]) + 22]
    : [T[0] - 22, T[1] + 26];
  halo(g.text('3').font({ size: 17, 'font-weight': 'bold', family: 'sans-serif', anchor: 'middle' })
    .fill(C_PURPLE).attr({ x: l3[0], y: l3[1] }));

  /* focal points */
  [Fn, Ff].forEach(function (Fp) {
    g.circle(11).center(Fp[0], Fp[1]).fill('#d43d3d');
    halo(g.text('F').font({ size: 16, family: 'Georgia, serif', 'font-style': 'italic', anchor: 'middle' })
      .fill('#b02a2a').attr({ x: Fp[0], y: axisY + 27 }));
    var hit = g.circle(16).center(Fp[0], Fp[1]).fill('#000').attr('fill-opacity', 0);
    clickable(hit, 'Focal point F', 'Focal point',
      'F sits one focal length (f = ' + f + ') from the lens center. Parallel rays bend through the far F; rays through the near F emerge parallel.');
  });

  /* object arrow + h_o dimension */
  var obj = g.group();
  obj.line(objX, axisY, objX, tipY).stroke({ color: C_RED, width: 5 });
  arrowHead(obj, objX, tipY, -Math.PI / 2, 12, C_RED);
  clickable(obj, 'Object — height h_o', 'Object',
    'The object of height h_o stands at distance d_o from the lens. Its tip is the common starting point of the three principal rays. Drag the d_o slider to move it.');
  var xHo = Math.max(30, objX - 52);
  vDim(g, xHo, tipY, axisY, C_DIM);
  subLabel(g, xHo + 16, (tipY + axisY) / 2 + 5, 'h', 'o', 16, C_DIM);

  /* image arrow + h_i dimension */
  if (imgOn) {
    var im = g.group();
    var ln = im.line(imgX, axisY, imgX, imgTipY).stroke({ color: C_RED, width: 5 });
    if (!real) ln.attr('stroke-dasharray', '6,4');
    arrowHead(im, imgX, imgTipY, real ? Math.PI / 2 : -Math.PI / 2, 12, C_RED);
    clickable(im, real ? 'Real image — inverted' : 'Virtual image — upright',
      real ? 'Real image' : 'Virtual image',
      real
        ? 'All three refracted rays actually meet here: a real, inverted image of height h_i at distance d_i. It could be projected on a screen.'
        : 'The refracted rays diverge on the right, but their dashed backward extensions meet here: an upright virtual image that cannot be projected on a screen.');
    var xHi = real ? Math.min(imgX + 38, 970) : Math.max(imgX - 42, 30);
    vDim(g, xHi, Math.min(imgTipY, axisY), Math.max(imgTipY, axisY), C_DIM);
    subLabel(g, xHi + 14, (axisY + imgTipY) / 2 + 5, 'h', 'i', 16, C_DIM);
  }

  /* brackets: f, d_o, d_i */
  dimBracket(g, lensX, Ff[0], 262, C_DIM, false);
  halo(g.text('f').font({ size: 16, family: 'Georgia, serif', 'font-style': 'italic', anchor: 'middle' })
    .fill(C_DIM).attr({ x: lensX + fPx / 2, y: 280 }));
  dimBracket(g, objX, lensX, 505, C_DIM, false);
  subLabel(g, (objX + lensX) / 2, 528, 'd', 'o', 16, C_DIM);
  if (real && imgOn) {
    dimBracket(g, lensX, imgX, 505, C_DIM, false);
    subLabel(g, (lensX + imgX) / 2, 528, 'd', 'i', 16, C_DIM);
  } else if (!real && isFinite(d_i) && imgX > 20) {
    dimBracket(g, imgX, lensX, 548, '#888', true);
    subLabel(g, (imgX + lensX) / 2, 571, 'd', 'i', 14, '#777');
    halo(g.text('(virtual)').font({ size: 11, family: 'sans-serif', anchor: 'middle' })
      .fill('#777').attr({ x: (imgX + lensX) / 2, y: 585 }));
  }

  /* measurement overlay */
  if (showMeas) {
    var lines;
    if (nearF) {
      lines = ['f   = ' + f.toFixed(1), 'd_o = ' + d_o.toFixed(1), 'd_i = ∞',
        'd_o = f : the refracted', 'rays emerge parallel —', 'no image is formed'];
    } else {
      var h_i = -d_i / d_o * h_o;
      lines = [
        'f   = ' + f.toFixed(1),
        'd_o = ' + d_o.toFixed(1),
        'd_i = ' + d_i.toFixed(1) + (real ? ' (real)' : ' (virtual)'),
        'h_o = ' + h_o.toFixed(1),
        'h_i = ' + h_i.toFixed(1),
        'm = -d_i/d_o = ' + (h_i / h_o).toFixed(2),
        '1/d_o+1/d_i = ' + (1 / d_o + 1 / d_i).toFixed(4),
        '1/f         = ' + (1 / f).toFixed(4) + '  ✓'
      ];
    }
    var boxH = lines.length * 16 + 14;
    var box = g.group();
    box.rect(258, boxH).move(722, 14)
      .attr({ fill: '#ffffff', 'fill-opacity': 0.94, stroke: '#b9c2cc', 'stroke-width': 1, rx: 6 });
    var tx = box.text(function (add) {
      lines.forEach(function (l) { add.tspan(l).newLine(); });
    });
    tx.font({ size: 12.5, family: 'ui-monospace, Consolas, monospace' }).fill('#1d1d1d').move(732, 22);
  }

  /* selection + emphasis markers */
  if (selectedRay === 1) pulse(g, Ff[0], Ff[1], 15);
  if (selectedRay === 2) pulse(g, C[0], C[1], 15);
  if (selectedRay === 3) pulse(g, Fn[0], Fn[1], 15);
  if (emphasizeImage && imgOn) pulse(g, imgX, imgTipY, 16);
}

/* click on empty background clears the ray selection */
draw.on('click', function (e) {
  if (e.target === draw.node) {
    if (selectedRay) { selectedRay = 0; render(); }
    hidePopup();
  }
});

/* ---------- controls ---------- */
function update_objectDistance(v) { d_o = v; render(); }
function toggle_measurementOverlay(on) { showMeas = on; render(); }

/* ---------- demo steps ---------- */
var steps = [
  { title: 'The three principal rays', narration: 'Three rays leave the object tip: one parallel to the axis bends through the far focal point, one passes straight through the lens center, and one through the near focal point emerges parallel. Click each ray to see its rule highlighted.', state: { objectDistance: 160, measurementOverlay: 'Ray construction' }, emphasize: false },
  { title: 'The rays agree on one image point', narration: 'All three rays cross at a single point below the axis — that crossing alone fixes the inverted real image of height h_i at distance d_i, with no calculation needed.', state: { objectDistance: 160, measurementOverlay: 'Ray construction' }, emphasize: true },
  { title: 'Attach the measurements', narration: 'Switching on the overlay attaches f, d_o, d_i, h_o, and h_i to the drawing, connecting the geometric construction to the lens equation and magnification.', state: { objectDistance: 160, measurementOverlay: 'Measurements' }, emphasize: false },
  { title: 'Move the object', narration: 'Drag the object toward the lens: the image recedes and grows; at d_o = f the rays emerge parallel and no image forms; inside f the rays diverge and only a virtual upright image appears where their backward extensions meet.', state: { objectDistance: 60, measurementOverlay: 'Measurements' }, emphasize: true }
];
var curStep = 0;
function applyStep(i) {
  curStep = i;
  var st = steps[i];
  d_o = st.state.objectDistance;
  showMeas = st.state.measurementOverlay === 'Measurements';
  emphasizeImage = !!st.emphasize;
  selectedRay = 0;
  document.getElementById('objectDistanceInput').value = d_o;
  document.getElementById('objectDistanceVal').value = d_o;
  document.getElementById('measurementOverlayInput').checked = showMeas;
  document.getElementById('demoNarration').innerHTML =
    '<b>Step ' + (i + 1) + ': ' + st.title + '.</b> ' + st.narration;
  document.getElementById('stepLabel').textContent = (i + 1) + ' / ' + steps.length;
  render();
}
function nextStep() { if (curStep < steps.length - 1) applyStep(curStep + 1); }
function prevStep() { if (curStep > 0) applyStep(curStep - 1); }

applyStep(0);
window.__markRendered();
